"""Generate aft.rb for a published release; never install or publish anything."""

import argparse
from pathlib import Path
import re


TARGETS = ("darwin-arm64", "darwin-amd64", "linux-arm64", "linux-amd64")


def formula(tag, checksums):
    """Require one SHA-256 per platform and render the repository's binary formula."""
    if not re.fullmatch(r"v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)", tag):
        raise ValueError("expected a stable vX.Y.Z tag")
    names = {f"aft-{tag}-{target}.tar.gz": target for target in TARGETS}
    sums = {}
    for line in checksums.splitlines():
        parts = line.split()
        if len(parts) != 2 or parts[1] not in names:
            raise ValueError("unexpected checksum entry")
        digest, name = parts
        target = names[name]
        if not re.fullmatch(r"[0-9a-f]{64}", digest) or target in sums:
            raise ValueError(f"invalid or duplicate checksum for {target}")
        sums[target] = digest
    if len(sums) != len(TARGETS):
        raise ValueError("checksums must include all four release archives")
    lines = [
        "# frozen_string_literal: true", "",
        "# Generated by .github/release/formula.py after publication; edit that script, not this file.",
        "class Aft < Formula",
        '  desc "Run terminal agents on your server while typing stays local"',
        '  homepage "https://github.com/fschrhunt/aft"',
        f'  version "{tag[1:]}"',
        '  license "MIT"', "",
        "  livecheck do", "    url :stable", "    strategy :github_latest", "  end", "",
    ]
    for os, section in (("darwin", "on_macos"), ("linux", "on_linux")):
        lines.append(f"  {section} do")
        for arch, block in (("arm64", "on_arm"), ("amd64", "on_intel")):
            target = f"{os}-{arch}"
            url = f"https://github.com/fschrhunt/aft/releases/download/{tag}/aft-{tag}-{target}.tar.gz"
            lines += [f"    {block} do", f'      url "{url}"',
                      f'      sha256 "{sums[target]}"', "    end"]
        lines += ["  end", ""]
    lines += ["  def install", '    bin.install "aft"', "  end", "",
              "  def caveats", '    "Next: aft setup"', "  end", "",
              "  test do", f'    assert_equal "aft {tag}", shell_output("#{{bin}}/aft version").strip',
              "  end", "end", ""]
    return "\n".join(lines)


def main():
    """Write a formula to stdout from the selected release's checksum manifest."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("tag")
    parser.add_argument("checksums", type=Path)
    args = parser.parse_args()
    try:
        print(formula(args.tag, args.checksums.read_text()), end="")
    except ValueError as error:
        parser.error(str(error))


if __name__ == "__main__":
    main()
